# Test User Login Endpoint
class TestUserLogin:
    """Test suite for the /user/login endpoint."""

    @pytest.mark.parametrize("username,password", [
        ("validuser", "validpassword"),  # Valid credentials
        ("", ""),  # Missing username and password
        ("wronguser", "wrongpassword"),  # Invalid credentials
    ])
    def test_login_response_codes(self, base_url, username, password):
        """
        Test /user/login endpoint with multiple response scenarios including valid, invalid, and empty parameters.
        """
        url = f"{base_url}/user/login"
        params = {
            "username": username,
            "password": password
        }

        try:
            response = requests.get(url, params=params)

            # Response assertions
            if username == "validuser" and password == "validpassword":
                assert response.status_code == 200, "Expected Status Code: 200"
                assert "X-Rate-Limit" in response.headers, "Missing X-Rate-Limit Header"
                assert "X-Expires-After" in response.headers, "Missing X-Expires-After Header"
            elif username == "" and password == "":
                assert response.status_code == 400, "Expected Status Code: 400"
            elif username != "validuser" or password != "validpassword":
                assert response.status_code == 400, "Expected Status Code: 400"
            else:
                pytest.fail(f"Unexpected response code received: {response.status_code}")
        except RequestException as err:
            pytest.fail(f"Request failed due to error: {err}")

    def test_login_missing_authentication(self, base_url):
        """
        Test /user/login endpoint without authentication headers.
        """
        url = f"{base_url}/user/login"
        params = {
            "username": "validuser",
            "password": "validpassword"
        }

        response = requests.get(url, params=params)
        assert response.status_code == 401 or response.status_code == 403, "Expected Status Code: 401/403 for missing authentication"

    def test_login_unexpected_error(self, base_url):
        """
        Test /user/login endpoint for handling unexpected errors.
        """
        url = f"{base_url}/invalid/login"  # Use an invalid URL to trigger an error
        params = {
            "username": "validuser",
            "password": "validpassword"
        }

        response = requests.get(url, params=params)

        # Unexpected error response
        assert response.status_code not in [200, 400], "Expected an error response not 200 or 400"
        assert "Unexpected error" in response.text, "Expected 'Unexpected error' message in response"

